-- ============================================================================
-- trenmap · carga de datos migrados desde SQLite
-- session_replication_role=replica desactiva triggers/FK durante la carga
-- masiva; se valida la integridad al reactivar el rol.
-- ============================================================================
BEGIN;
SET session_replication_role = replica;

-- notes (8 filas)

-- marital_status (6 filas)

-- relationship_type (17 filas)

-- organization (136 filas)

-- contact (571 filas)

-- contact_relationship (12 filas)

-- contact_organization (220 filas)

-- national_identity_card (344 filas)

-- contact_phone (272 filas)

-- contact_email (299 filas)

-- contact_note (219 filas)

-- contact_url (62 filas)

-- contact_bank_account (23 filas)


-- Limpieza: status_id vacios de origen -> NULL (316 casos)
UPDATE contact SET status_id = NULL WHERE status_id = '';

SET session_replication_role = DEFAULT;

-- Reajuste de secuencias IDENTITY al MAX(id) cargado
SELECT setval(pg_get_serial_sequence('notes','id'), (SELECT COALESCE(MAX(id),1) FROM notes));
SELECT setval(pg_get_serial_sequence('contact_relationship','id'), (SELECT COALESCE(MAX(id),1) FROM contact_relationship));
SELECT setval(pg_get_serial_sequence('contact_organization','id'), (SELECT COALESCE(MAX(id),1) FROM contact_organization));
SELECT setval(pg_get_serial_sequence('national_identity_card','id'), (SELECT COALESCE(MAX(id),1) FROM national_identity_card));
SELECT setval(pg_get_serial_sequence('contact_phone','id'), (SELECT COALESCE(MAX(id),1) FROM contact_phone));
SELECT setval(pg_get_serial_sequence('contact_email','id'), (SELECT COALESCE(MAX(id),1) FROM contact_email));
SELECT setval(pg_get_serial_sequence('contact_note','id'), (SELECT COALESCE(MAX(id),1) FROM contact_note));
SELECT setval(pg_get_serial_sequence('contact_url','id'), (SELECT COALESCE(MAX(id),1) FROM contact_url));
SELECT setval(pg_get_serial_sequence('contact_bank_account','id'), (SELECT COALESCE(MAX(id),1) FROM contact_bank_account));

COMMIT;
